def solve():
    n = 10
    m = 5
    # a_{m,j} = sum_{i=0}^{n-1} c_{m,j,i} a_{0,i}
    # c_{m,j,i} is the coefficient of a_{0,i} in a_{m,j}
    # a_{0,i} = i+1
    # We want to find the number of j such that a_{m,j} = 2013.
    # First, find c_{m,j,i}
    # Initial: c_{0,i,i} = 1, all others 0.
    coeffs = [[0]*n for _ in range(n)]
    for i in range(n):
        coeffs[i][i] = 1

    for _ in range(m):
        new_coeffs = []
        # a_{m+1, 2j} = a_{m,j}
        # a_{m+1, 2j+1} = a_{m,j} + a_{m,j+1}
        # Number of elements after m steps is 2^m(n-1)+1
        # But we can just keep the coeffs as we go.
        num_elements = len(coeffs)
        new_coeffs = [[0]*n for _ in range(2*num_elements - 1)]
        for j in range(num_elements):
            # a_{m+1, 2j}
            for i in range(n):
                new_coeffs[2*j][i] = coeffs[j][i]
            # a_{m+1, 2j+1}
            if j+1 < num_elements:
                for i in range(n):
                    new_coeffs[2*j+1][i] = coeffs[j][i] + coeffs[j+1][i]
            else:
                # this case shouldn't happen if we're careful
                for i in range(n):
                    new_coeffs[2*j+1][i] = coeffs[j][i]
        coeffs = new_coeffs

    # Now calculate a_{m,j} = sum c_{m,j,i} * (i+1)
    count = 0
    for j in range(len(coeffs)):
        val = sum(coeffs[j][i] * (i+1) for i in range(n))
        if val == 2013:
            count += 1
    return count

