    # We want to find the number of j such that a_{m,j} = 2013.
    # Let's look at a_{m,j} for small m, n.
    # a_{m,j} = sum c_{m,j,i} (i+1)
    # c_{m,j,i} is the number of paths from (m,j) to (0,i).
    # c_{m,j,i} follows c_{m+1, 2j, i} = c_{m,j,i}
    # c_{m+1, 2j+1, i} = c_{m,j,i} + c_{m,j+1, i}

    # Let's re-calculate c_{m,j,i} for small m, n.
    n = 10
    m_test = 5
    coeffs = [[0]*n for _ in range(n)]
    for i in range(n):
        coeffs[i][i] = 1

    for _ in range(m_test):
        new_coeffs = []
        num_elements = len(coeffs)
        new_coeffs = [[0]*n for _ in range(2*num_elements - 1)]
        for j in range(num_elements):
            for i in range(n):
                new_coeffs[2*j][i] = coeffs[j][i]
            if j+1 < num_elements:
                for i in range(n):
                    new_coeffs[2*j+1][i] = coeffs[j][i] + coeffs[j+1][i]
            else:
                for i in range(n):
                    new_coeffs[2*j+1][i] = coeffs[j][i]
        coeffs = new_coeffs

    # a_{m,j} = sum c_{m,j,i} * (i+1)
    # We want to see how a_{m,j} behaves.
    results = []
    for j in range(len(coeffs)):
        val = sum(coeffs[j][i] * (i+1) for i in range(n))
        results.append(val)
    return results

