def get_coefficients(k, n0):
    # b_{k,j} = sum_i C(k,j,i) * x_i
    # C(0,j,i) = 1 if j=i else 0
    # C(k, 2j-1, i) = C(k-1, j, i)
    # C(k, 2j, i) = C(k-1, j, i) + C(k-1, j+1, i)

    # Initial coefficients at k=0
    # coeffs[j] is a dictionary {i: coefficient}
    coeffs = [{i: 1} for i in range(1, n0 + 1)]

    for _ in range(k):
        new_coeffs = []
        for j in range(1, len(coeffs) + 1):
            # b_{k+1, 2j-1} = b_{k,j}
            new_coeffs.append(coeffs[j-1])
            # b_{k+1, 2j} = b_{k,j} + b_{k,j+1}
            # we need to handle the last element carefully
            if j < len(coeffs):
                combined = coeffs[j-1].copy()
                for i, val in coeffs[j].items():
                    combined[i] = combined.get(i, 0) + val
                new_coeffs.append(combined)
            else:
                # This case should not happen if the logic is correct
                # because b_{k+1, 2j} = b_{k,j} + b_{k,j+1}
                # and the number of elements is n_{k+1} = 2*n_k - 1
                # So the indices j go from 1 to n_k.
                # The even indices are 2, 4, ..., 2*n_k - 2.
                # Wait, the number of elements n_{k+1} is 2*n_k - 1.
                # The even indices are 2, 4, ..., 2*(n_k-1).
                # The even index 2j exists only if 2j <= 2*n_k - 1, which means j <= n_k - 1.
                # So we only need to go up to j = n_k - 1.
                pass

        # Let's re-trace:
        # n_k elements: b_{k,1}, ..., b_{k,n_k}
        # n_{k+1} elements: b_{k+1,1}, ..., b_{k+1,2n_k-1}
        # b_{k+1, 2j-1} = b_{k,j} for j = 1, ..., n_k
        # b_{k+1, 2j} = b_{k,j} + b_{k,j+1} for j = 1, ..., n_k-1

        # Let's rewrite the loop:
        new_coeffs = []
        for j in range(1, len(coeffs) + 1):
            new_coeffs.append(coeffs[j-1]) # b_{k+1, 2j-1}
            if j < len(coeffs):
                combined = coeffs[j-1].copy()
                for i, val in coeffs[j].items():
                    combined[i] = combined.get(i, 0) + val
                new_coeffs.append(combined) # b_{k+1, 2j}
        coeffs = new_coeffs
    return coeffs

